def solve(g,corner):
    H=len(g);W=len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cs=comps4(g)
    objs=[(v,c) for v,c in cs if len(c)>1 and v!=bg]
    marks=[]
    adj=set()
    for v,S in cs:
        for r,c in S:
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    adj.add((r+dy,c+dx))
    for v,m in cs:
        if len(m)==1: marks.append(list(m)[0])
    out=[row[:] for row in g]
    for v,S in objs:
        rs=[p[0] for p in S]; cc2=[p[1] for p in S]
        r0,r1=min(rs),max(rs); c0,c1=min(cc2),max(cc2)
        mname={'tl':lambda mr,mc:(mr-r0,mc-c0),'bl':lambda mr,mc:(mr-r1,mc-c0),'tr':lambda mr,mc:(mr-r0,mc-c1),'br':lambda mr,mc:(mr-r1,mc-c1)}
        off=mname[corner]
        for mr,mc in marks:
            if (mr,mc) in adj: continue
            drr,dc=off(mr,mc)
            for r,c in S:
                nr,nc=r+drr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]==bg: out[nr][nc]=v
    return out
for k in ('Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4'):
    go=G[k+' output']; pred=solve(G[k+' input'],'bl')
    bad=[(r,c,pred[r][c],go[r][c]) for r in range(len(go)) for c in range(len(go[0])) if pred[r][c]!=go[r][c]]
    print(k,'match' if not bad else 'nbad=%d'%len(bad), bad[:6])

