def solve(g):
    H=len(g);W=len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cs=comps4(g)
    objs=[(v,c) for v,c in cs if len(c)>1 and v!=bg]
    marks=[]
    adj=set()
    for v,S in cs:
        for r,c in S:
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    adj.add((r+dy,c+dx))
    for v,m in cs:
        if len(m)==1: marks.append((v,list(m)[0]))
    out=[row[:] for row in g]
    for v,m in marks:
        if (m[0],m[1]) in adj: continue
        best=None
        for ov,O in objs:
            rs=[p[0] for p in O]; cc2=[p[1] for p in O]
            r0,r1=min(rs),max(rs); c0,c1=min(cc2),max(cc2)
            rel=(m[0]-r1, m[1]-c0)   # rel of this marker within bbox of THIS object
            # stamp object O so that marker m is at rel within O's bbox -> O TL = m - rel
            TL=(m[0]-rel[0], m[1]-rel[1])
            score=abs(m[0]-TL[0])+abs(m[1]-TL[1])
            if best is None or score<best[0]: best=(score,ov,O,TL)
        if best is None: continue
        _,ov,O,TL=best
        for r,c in O:
            nr,nc=r+(TL[0]-min(p[0] for p in O))+0 if False else r+TL[0]-min(p[0] for p in O)
            nr,nc=r+TL[0]-min(p[0] for p in O), c+TL[1]-min(p[1] for p in O)
            if 0<=nr<H and 0<=nc<W and g[nr][nc]==bg: out[nr][nc]=ov
    return out
for k in ('Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4'):
    go=G[k+' output']; pred=solve(G[k+' input'])
    bad=[(r,c,pred[r][c],go[r][c]) for r in range(len(go)) for c in range(len(go[0])) if pred[r][c]!=go[r][c]]
    print(k,'match' if not bad else f'nbad={len(bad)} {bad[:8]}')
